    }
}

module hook_profile(){
    // 2D profile in YZ plane, oriented with Y vertical, Z outward from wall.
    // Designed to stay within plate height (-20..20)
    polygon([
        [-10, 6],   // attach lower near plate face
        [-10, 32],
        [ 20, 32],
        [ 20, 25],
        [  5, 25],
        [  5, 6]
    ]);
}

module hook_body(){
    // Extrude profile along X for hook width
    linear_extrude(height=hook_width, center=true)
        hook_profile();
